import {
  PERMISSIONS,
  TENANT_ROLE_KEYS,
  TENANT_ROLES,
  type PermissionKey,
} from "@gym/core/authz";
import {
  PLATFORM_PERMISSIONS,
  type PlatformPermissionKey,
} from "@gym/core/platform";
import { PLATFORM_ROLE_PERMISSIONS, ROLE_PERMISSIONS } from "./permissions";

/** docs/PERMISSIONS.md, generated from the matrix so the doc can never drift. */
export function renderPermissionsDoc(): string {
  const roleHeads = TENANT_ROLE_KEYS.map((k) => TENANT_ROLES[k].label);
  const lines: string[] = [
    "# Permissions",
    "",
    "<!-- Generated by `pnpm docs:permissions` from packages/auth/src/permissions.ts. Do not edit by hand. -->",
    "",
    "Code checks permission keys, never role names (D-07). **Scope** `tenant` means only a role assigned to",
    "all branches grants it; `branch` means a role assigned to one branch grants it for that branch only.",
    "",
    "## Tenant realm (apps/web)",
    "",
    `| Permission | Scope | What it allows | ${roleHeads.join(" | ")} |`,
    `| --- | --- | --- | ${roleHeads.map(() => ":---:").join(" | ")} |`,
  ];
  for (const [key, meta] of Object.entries(PERMISSIONS) as [
    PermissionKey,
    (typeof PERMISSIONS)[PermissionKey],
  ][]) {
    const cells = TENANT_ROLE_KEYS.map((role) =>
      ROLE_PERMISSIONS[role].includes(key) ? "✓" : "",
    );
    lines.push(
      `| \`${key}\` | ${meta.scope} | ${meta.description} | ${cells.join(" | ")} |`,
    );
  }
  lines.push(
    "",
    "### Second factor (D-03)",
    "",
    "| Role | Email OTP |",
    "| --- | --- |",
    ...TENANT_ROLE_KEYS.map((role) => {
      const mfa = TENANT_ROLES[role].mfa;
      const text =
        mfa === "required"
          ? "Always (no trusted-device skip)"
          : mfa === "tenant-setting"
            ? "When the gym requires it (trusted device allowed for 30 days)"
            : "Optional, off by default";
      return `| ${TENANT_ROLES[role].label} | ${text} |`;
    }),
    "",
    "## Platform realm (apps/admin)",
    "",
    "Every platform user signs in with email + password and a mandatory email OTP.",
    "",
    "| Permission | What it allows | Super Admin | Platform Support |",
    "| --- | --- | :---: | :---: |",
  );
  for (const [key, description] of Object.entries(PLATFORM_PERMISSIONS) as [
    PlatformPermissionKey,
    string,
  ][]) {
    const sa = PLATFORM_ROLE_PERMISSIONS.SUPER_ADMIN.includes(key) ? "✓" : "";
    const sp = PLATFORM_ROLE_PERMISSIONS.SUPPORT.includes(key) ? "✓" : "";
    lines.push(`| \`${key}\` | ${description} | ${sa} | ${sp} |`);
  }
  lines.push("");
  return lines.join("\n");
}
